from collections import deque

def solve(x, s):
    q = deque()
    for char in x:
        if len(s) > len(q):
            return -1  # early exit condition for performance optimization
        while len(q) != 0 and ''.join(q) + ''.join(q)[-len(s):] != s:
            if len(s) > len(q):
                q.popleft()
        q.append(char)
    if s in q:  # check if the substring appears in the deque
        return len(q) // len(s)
    else:
        return -1

