def solve():
    n = int(input())
    p = list(map(lambda x: int(x) - 1, input().split()))
    ans = sum(1 for i in range(n) if i == p[i])
    cnts = {}
    for i in p:
        if i not in cnts:
            cnts[i] = 0
        cnts[i] += 1
    pairs_count = 0
    for k, v in cnts.items():
        if v % 2:
            return sys.maxsize # Explicit handling of this condition.
        else:
            pairs_count += (v // 2) * ((v - 1) // 2 + 1)
    print((ans + min(ans << 1, n - 1 - ans)) >> 1)

