class Reader(object):
    def __init__(self):
        self.input = iter(input())
        self.peeked = None

    def nextLine(self):
        self.peeked = None
        return next(self.input).strip()

    def hasNext(self):
        return True

    def nextInt(self, n=1):
        if self.peeked is None:
            s = ''
            while not (s + '.').replace('.', '.')[0] in '0123456789-':
                c = next(self.input, '[EOF]').strip()
                if c == '[' or c == '':
                    raise EOFError
                self.peeked = c
        while self.peeked and self.peeked[0] in '0123456789.':
            s += self.peeked[0]
            self.peeked = self.peeked[1:]
        val = int(s)
        if self.peeked == '-':
            raise ValueError("Unexpected minus sign.")
        return val

