                        new_num = perfect_array[num - 1] + 1
                        perfect_array[num - 1] = new_num

                        new_sum = sum(perfect_array)
                        is_divisible_by_n = (new_sum % n == 0)
                        if is_divisible_by_n:
                            break
                    else:
                        next_number_to_check.reverse()
                        next_number = next_number_to_check.pop()

                        perfect_array[next_number - 1] += n

            print(*perfect_array)

