def solve(a, b, c, d):
    # Check if we can reach point(c,d)
    if c < a or d < b:
        return -1  # Movement to the destination is impossible

    elif (c - a) == 0 and (d - b) > 0:
        return -1

    else:
        x = max(d-b, c-a)
        y = min((c-b), (a-d))

        if y < 0: # Handle the case when we need to go down more steps
            num_down_steps_to_reach_top_level = abs(y) + x        
        else:
            return -1

        return x + abs(y)

