from itertools import groupby

def solve(s):
    # Convert string to lowercase
    s = s.lower()

    # Count occurrences of each character type ('m', 'e', 'o', or 'w')
    counts = {'m': False, 'e': False, 'o': False, 'w': False}

    for k in groupby(s):
        char = k[0]

        if char in ['m', 'M']:
            counts['m'] = True

        elif char in ['e', 'E']:
            if not counts['m']:
                return "NO"

            counts['e'] = True

        elif char in ['o', 'O']:
            if not (counts['e']):
                return "NO"

            counts['o'] = True

        elif char in ['w', 'W']:
            if not (counts['o']):
                return "NO"

            counts['w'] = True

    # Check edge cases 
    if len(s) > 0 and (not re.fullmatch('[mw]+$', s)):
        return "NO"

    return "YES" if all(counts.values()) else "NO"

