import heapq

def solve():
    q = []
    n = int(input())
    arr = list(map(int, input().split()))
    total_sum = sum(arr)

    for i in range(1, n):
        if arr[i] < arr[0]:
            heapq.heappush(q, (arr[i]*(n-1) - arr[0]*(n-2), i))

    cur_diff = 0
    while q:
        diff, x = heapq.heappop(q)
        diff -= cur_diff*(n-1)

        if diff < 0:
            break

        if arr[x] >= total_sum // n:
            return sys.stdout.write(str(total_sum) + '\n')

        cur_diff += (diff % (n - 1))

    return sys.stdout.write(str(arr[0] + cur_diff*(n-1)) + '\n')

