    cases = int(input())
    for _ in range(cases):
        n, c = map(int, input().split())
        nums = list(map(int, input().split()))

        # Count the number of each unique value in the list
        value_counts = {}
        for num in nums:
            if num not in value_counts:
                value_counts[num] = 0
            value_counts[num] += 1

        # Calculate the total cost of using the second machine once on each unique value
        total_cost_2nd_machine = sum(min(value * c, value) for value in value_counts.values())

        # Check if all values have only one occurrence
        if all(count == 1 for count in value_counts.values()):
            total_cost_1st_machine = n
        else:
            # Determine the cost of using the first machine
            max_value = max(value_counts.keys())
            remaining_values = {
                key: val // max_value * max_value for key, val in value_counts.items()
            }

            # Calculate the remaining values that are not multiples of max_value
            orbit_remainders = [
                num % max_value for num in [val - val // max_value * max_value if (val := i) else 0 for i in value_counts.values()]
            ]

            total_cost_1st_machine = n
            while any(orbit_remainders):
                min_orbit_remainder = min(orbit_remainders)
                index_min_remainder = orbit_remainders.index(min_orbit_remainder)

                # Simplify the code using list comprehension instead of for loop
                orbit_remainders[index_min_remainder] -= min_orbit_remainder
            del remaining_values

        total_cost_1st_machine = 0 if n == 1 else total_cost_1st_machine


        print(min(total_cost_2nd_machine, total_cost_1st_machine))

