def solve(n):
    result = [n]*2 if n % 2 else [n - 1] * (n // 2 + 1)
    for i in range(1, n + 1):
        idx = next((i for j, x in enumerate(result) if x > i), None)
        if idx is not None:
            result[idx-1] = i
    return [x if x != 0 else '' for x in result]

