def lcm(a, b):
    """Compute Least Common Multiple of a and b"""
    return abs(a*b) // math.gcd(a, b)

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        count = 0

        # Process multiples of each number up to n
        for num in range(1, n + 1):
            if num % 2 == 1:
                # Even numbers and their LCM will be >3 times the GCD only with another even number,
                # which itself would also have a LCM that's divisible by num.
                count += 4
            else:
                multiplier = math.floor(n / num)
                count += multiplier * (multiplier + 1) // 2

        print(count)

