    t = int(input())
    for _ in range(t):
        n = int(input())
        nums = list(map(int, input().split()))
        has_common_divisor = False
        common_multiplier = 0

        def gcd(a, b):
            nonlocal common_multiplier
            while a != 0 and b != 0:
                if a > b:
                    a %= b
                else:
                    b %= a
            return a + b, (a * b) // ((a + b))

        for i in range(1, n):
            divisor = gcd(nums[0], nums[i])
            common_multiplier += nums[0] // divisor

            if nums[i] % nums[0]> 0:
                has_common_divisor = True
            else:
                has_common_divisor = False
                break

        print(["NO", "YES"][has_common_divisor and not common_multiplier > 1])

